import { Group, Mesh, PlaneGeometry, Vector3, type Camera, type Texture } from 'three';
import { avatarMaterial } from './materials';
import { tagInteractive } from './corridor';
import type { SketchMaterial } from './materials';

/**
 * Hand-drawn avatar: a flipbook sprite (16 frames in a 4×4 KTX2 atlas,
 * generated by scripts/avatar-frames.mjs) on a plane that turns to face the
 * camera. It idles with a hand-drawn "line boil", waves when you walk up to it,
 * now and then while you're nearby, and whenever it's hovered or clicked.
 */
const GRID = 4;
const IDLE = [0, 1, 2];
const RAISE = [3, 4, 5, 6];
const WAVE = [7, 8, 9, 10, 11, 12, 13, 14];
const WAVE_SEQ = [...RAISE, ...WAVE, ...WAVE, ...[...RAISE].reverse()];
const IDLE_FPS = 4;
const WAVE_FPS = 12;

// Frame layout (from avatar-frames.mjs): 512×1024 cell, figure centred at x=200,
// feet at y≈958. The plane is offset so the pivot sits between the feet.
const HEIGHT = 2.0;
const WIDTH = 1.0;
const FEET_V = 1 - 958 / 1024;
const CENTRE_U = 200 / 512;

export interface Avatar {
  group: Group;
  mesh: Mesh;
  wave(): void;
  /** Advances the animation; returns true when something on screen changed. */
  update(dt: number, camera: Camera): boolean;
}

const tmp = new Vector3();

export function createAvatar(opts: {
  sketch: Texture;
  painted: Texture;
  id: string;
  position: [number, number, number];
  reducedMotion: boolean;
  /** Wave when the camera comes within this distance (metres). */
  greetDistance?: number;
}): Avatar {
  const mat = avatarMaterial(opts.sketch, opts.painted, GRID);
  const geo = new PlaneGeometry(WIDTH, HEIGHT);
  geo.translate((0.5 - CENTRE_U) * WIDTH, HEIGHT / 2 - FEET_V * HEIGHT, 0);
  const mesh = new Mesh(geo, mat);
  mesh.name = `avatar-${opts.id}`;
  const group = new Group();
  group.add(mesh);
  group.position.set(...opts.position);
  tagInteractive(mesh, { kind: 'avatar', id: opts.id, paint: [mat as unknown as SketchMaterial] });

  const greet = opts.greetDistance ?? 8;
  let queue: number[] = [];
  let frame = 0;
  let acc = 0;
  let idleIndex = 0;
  let greeted = false;
  let sinceWave = 0;
  let nextAutoWave = 6 + Math.random() * 4;
  let yaw = 0;

  const setFrame = (f: number) => {
    if (f === frame) return false;
    frame = f;
    mat.uniforms.uFrame.value = f;
    return true;
  };

  const avatar: Avatar = {
    group,
    mesh,
    wave() {
      if (opts.reducedMotion) return;
      if (queue.length > WAVE.length) return; // already mid-wave
      queue = [...WAVE_SEQ];
      acc = 1 / WAVE_FPS; // start on the next tick
      sinceWave = 0;
      nextAutoWave = 7 + Math.random() * 5;
    },
    update(dt, camera) {
      let changed = false;
      // camera in the avatar's parent space (avatars can live inside a rotated room)
      const cam = group.parent ? group.parent.worldToLocal(tmp.copy(camera.position)) : tmp.copy(camera.position);
      const dx = cam.x - group.position.x;
      const dz = cam.z - group.position.z;
      const dist = Math.hypot(dx, dz);

      // turn to face the camera (yaw only), eased
      const target = Math.atan2(dx, dz);
      let diff = target - yaw;
      diff = Math.atan2(Math.sin(diff), Math.cos(diff));
      if (Math.abs(diff) > 1e-4) {
        yaw += diff * (opts.reducedMotion ? 1 : 1 - Math.exp(-dt * 6));
        group.rotation.y = yaw;
        group.updateMatrixWorld(true);
        changed = true;
      }
      if (opts.reducedMotion || dist > 18) return changed;

      // greetings
      sinceWave += dt;
      if (!greeted && dist < greet) {
        greeted = true;
        avatar.wave();
      } else if (dist < greet + 1 && queue.length === 0 && sinceWave > nextAutoWave) {
        avatar.wave();
      }
      if (dist > greet + 4) greeted = false; // greet again next time you come back

      // flipbook
      acc += dt;
      if (queue.length) {
        while (acc >= 1 / WAVE_FPS && queue.length) {
          acc -= 1 / WAVE_FPS;
          changed = setFrame(queue.shift()!) || changed;
        }
      } else if (acc >= 1 / IDLE_FPS) {
        acc = 0;
        idleIndex = (idleIndex + 1) % IDLE.length;
        changed = setFrame(IDLE[idleIndex]) || changed;
      }
      return changed;
    },
  };
  return avatar;
}
